fn reverse(a: &Vec<char>) -> Vec<char> {
    // Preallocate a new Vec with the same length as `a`
    let mut b = Vec::with_capacity(a.len());
    // Iterate over `a` in reverse order, cloning each character into `b`
    for &ch in a.iter().rev() {
        b.push(ch);
    }
    b
}

